import type { ParsedFile, ValidationResult, ValidationRule } from "./types";

export function canteenValidChildrenMaxPoints(_rules: ValidationRule[]): number {
  return 100;
}

/**
 * The valid-children list is generated by an automation, so the checklist only
 * confirms the workbook was produced and the recon actually had payments.
 * Rounded or merged-name flags live in the workbook for a person to review;
 * they do not cost the automation points.
 */
export async function canteenValidChildrenValidator(
  files: ParsedFile[],
  _rules: ValidationRule[],
): Promise<ValidationResult> {
  const meta = files[0]?.statement.metadata ?? {};
  const hasSummary = Number(meta.hasSummary ?? 0) === 1;
  const valid = typeof meta.validChildren === "number" ? meta.validChildren : null;
  const flagged = typeof meta.flaggedChildren === "number" ? meta.flaggedChildren : 0;

  const checklist: ValidationResult["checklist"] = [
    {
      title: "Report generated",
      status: hasSummary ? "pass" : "fail",
      explanation: hasSummary ? "Summary sheet found." : "The workbook has no Summary sheet.",
      severity: "critical",
      points: hasSummary ? 50 : 0,
      maxPoints: 50,
    },
    {
      title: "Valid children found",
      status: valid !== null && valid > 0 ? "pass" : "fail",
      explanation:
        valid !== null && valid > 0
          ? `${valid} children are valid to eat on this date.`
          : "No children were valid on this date — check the Canteen Sales Recon payments.",
      severity: "high",
      points: valid !== null && valid > 0 ? 50 : 0,
      maxPoints: 50,
    },
  ];
  return {
    score: checklist.reduce((sum, c) => sum + c.points, 0),
    checklist,
    summary:
      valid === null
        ? "Valid children could not be counted."
        : `${valid} children valid to eat` + (flagged ? `; ${flagged} flagged for review (see the Flags sheet).` : "."),
    recommendations: flagged ? ["Review the Flags sheet for rounded payments and merged names."] : [],
  };
}
